Here's a clean approach using ASP.NET Core's built-in `IExceptionHandler` (available in .NET 8+) combined with Problem Details:

**1. Register Problem Details and a global exception handler:**

```csharp
// GlobalExceptionHandler.cs
using Microsoft.AspNetCore.Diagnostics;
using Microsoft.AspNetCore.Mvc;

public class GlobalExceptionHandler : IExceptionHandler
{
    private readonly ILogger<GlobalExceptionHandler> _logger;

    public GlobalExceptionHandler(ILogger<GlobalExceptionHandler> logger)
    {
        _logger = logger;
    }

    public async ValueTask<bool> TryHandleAsync(
        HttpContext httpContext,
        Exception exception,
        CancellationToken cancellationToken)
    {
        var (statusCode, title) = exception switch
        {
            KeyNotFoundException   => (StatusCodes.Status404NotFound, "Resource not found"),
            ArgumentException      => (StatusCodes.Status400BadRequest, "Invalid request"),
            InvalidOperationException => (StatusCodes.Status409Conflict, "Conflict"),
            _ => (StatusCodes.Status500InternalServerError, "An unexpected error occurred")
        };

        _logger.LogError(exception, "Unhandled exception: {Message}", exception.Message);

        var problemDetails = new ProblemDetails
        {
            Status = statusCode,
            Title = title,
            // Only expose exception message for client errors, not 500s
            Detail = statusCode < 500 ? exception.Message : null,
            Instance = httpContext.Request.Path
        };

        httpContext.Response.StatusCode = statusCode;
        await httpContext.Response.WriteAsJsonAsync(problemDetails, cancellationToken);

        return true; // Signal that the exception was handled
    }
}
```

**2. Wire it up in `Program.cs`:**

```csharp
var builder = WebApplication.CreateBuilder(args);

// Add Problem Details support
builder.Services.AddProblemDetails();

// Register the global exception handler
builder.Services.AddExceptionHandler<GlobalExceptionHandler>();

var app = builder.Build();

// Must come early in the pipeline
app.UseExceptionHandler();

// Your endpoints — no try-catch needed
app.MapGet("/items/{id}", (int id) =>
{
    if (id == 0) throw new KeyNotFoundException($"Item {id} not found");
    if (id < 0) throw new ArgumentException("ID must be positive");
    return Results.Ok(new { Id = id, Name = "Example" });
});

app.Run();
```

**Example 404 response:**

```json
{
  "status": 404,
  "title": "Resource not found",
  "detail": "Item 0 not found",
  "instance": "/items/0"
}
```

**Key points:**
- `IExceptionHandler` is the modern replacement for `UseExceptionHandler(lambda)` — it's DI-friendly and composable
- You can register multiple handlers; they run in order until one returns `true`
- 500 responses intentionally omit `Detail` to avoid leaking stack traces
- `AddProblemDetails()` also makes built-in responses (404 from routing, 400 from model binding) use Problem Details format
